.viewport {
  --ck-scrolling-label-speed-em-per-second: 1.9;
  --ck-scrolling-label-gap: 1.2em;
  --ck-scrolling-label-left-fade: 0.6em;
  --ck-scrolling-label-right-fade: 1.2em;
  --ck-scrolling-label-scroll-direction: -1;
  --ck-scrolling-label-mask-direction: to right;
  white-space: nowrap;
  width: 100%;
  min-width: 0;
  display: block;
}

.viewport:is(
  :lang(ae),
  :lang(ar),
  :lang(arc),
  :lang(bcc),
  :lang(bqi),
  :lang(ckb),
  :lang(dv),
  :lang(fa),
  :lang(glk),
  :lang(he),
  :lang(ku),
  :lang(mzn),
  :lang(nqo),
  :lang(pnb),
  :lang(ps),
  :lang(sd),
  :lang(ug),
  :lang(ur),
  :lang(yi)
) {
  --ck-scrolling-label-scroll-direction: 1;
  --ck-scrolling-label-mask-direction: to left;
}

.clipViewport {
  width: calc(100% + var(--ck-scrolling-label-left-fade));
  min-width: 0;
  margin-inline-start: calc(-1 * var(--ck-scrolling-label-left-fade));
