  display: inline-block;
}

.overflowingViewport {
  -webkit-mask-image: linear-gradient(
    var(--ck-scrolling-label-mask-direction),
    transparent,
    var(--ck-mask) var(--ck-scrolling-label-left-fade),
    var(--ck-mask) calc(100% - var(--ck-scrolling-label-right-fade)),
    transparent
  );
  mask-image: linear-gradient(
    var(--ck-scrolling-label-mask-direction),
    transparent,
    var(--ck-mask) var(--ck-scrolling-label-left-fade),
    var(--ck-mask) calc(100% - var(--ck-scrolling-label-right-fade)),
    transparent
  );
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
}

.overflowingViewport:is(
  :lang(ae),
  :lang(ar),
  :lang(arc),
  :lang(bcc),
  :lang(bqi),
  :lang(ckb),
  :lang(dv),
  :lang(fa),
  :lang(glk),
  :lang(he),
  :lang(ku),
  :lang(mzn),
  :lang(nqo),
  :lang(pnb),
  :lang(ps),
  :lang(sd),
  :lang(ug),
  :lang(ur),
  :lang(yi)
) {
  -webkit-mask-position: 100% 0;
  mask-position: 100% 0;
}

.animate .scrolling,
:global(.group):hover .animateOnGroupHover .scrolling {
  animation: ckMarqueeScroll var(--ck-scrolling-label-duration)
    var(--ck-scrolling-label-scroll-timing) infinite;
